// Route: vault.lynxmotorsports.racing/swvault-invites/download*
// R2 public custom domain: downloads.lynxmotorsports.racing
// Keep /swvault-invites/installer/latest on the existing invites service.
// All versions are resolved from that service so old 1.2.9 clients still work.
// R2 release files are populated by .github/workflows/release.yml.
// If R2 is unavailable, the original server remains a safe download fallback.

const R2_BASE = 'https://downloads.lynxmotorsports.racing';
const TEAM = 'LYNXFSAE'; // Only used for older manually uploaded builds without a manifest.
const MANIFEST_PREFIX = 'releases';

function safeVersion(value) {
  const version = String(value || '');
  return /^\d+\.\d+\.\d+$/.test(version) ? version : null;
}

function sanitizeAsset(name, version, extension) {
  if (typeof name !== 'string') return null;
  if (!/^SwVault-[A-Za-z0-9_-]+-\d+\.\d+\.\d+(-Setup)?\.(zip|exe)$/.test(name)) return null;
  if (!name.endsWith(`-${version}${extension}`)) return null;
  return name;
}

function directResponse(request, asset, filename, source) {
  const headers = new Headers(asset.headers);
  headers.set('Content-Type', filename.endsWith('.exe') ? 'application/vnd.microsoft.portable-executable' : 'application/zip');
  headers.set('Content-Disposition', `attachment; filename="${filename}"`);
  headers.set('Accept-Ranges', 'bytes');
  headers.set('Cache-Control', 'private, no-store');
  headers.set('X-SwVault-Installer-Source', source);
  headers.set('X-Content-Type-Options', 'nosniff');
  return new Response(request.method === 'HEAD' ? null : asset.body, { status: asset.status, headers });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== '/swvault-invites/download' || !['GET', 'HEAD'].includes(request.method)) {
      return fetch(request);
    }
    const format = (url.searchParams.get('format') || '').toLowerCase();
    if (!format && (request.headers.get('accept') || '').includes('text/html')) {
      return fetch(request); // Existing invite page, generated by the server.
    }

    const origin = async () => {
      const result = await fetch(request);
      const headers = new Headers(result.headers);
      headers.set('X-SwVault-Installer-Source', 'origin-fallback');
      return new Response(request.method === 'HEAD' ? null : result.body, {status: result.status, headers});
    };

    try {
      const latestUrl = new URL('/swvault-invites/installer/latest', url);
      const latestResponse = await fetch(latestUrl, {headers: {Accept: 'application/json'}, cf: {cacheTtl: 0}});
      if (!latestResponse.ok) return origin();
      const latest = await latestResponse.json();
      const version = safeVersion(latest.version);
      if (!version) return origin();

      const basePath = `${MANIFEST_PREFIX}/${version}/`;
      let manifest = null;
      const manifestResponse = await fetch(`${R2_BASE}/${basePath}manifest.json`, {cf: {cacheTtl: 0}});
      if (manifestResponse.ok) {
        manifest = await manifestResponse.json();
        if (manifest.version !== version || manifest.schema !== 1) return origin();
        // The Windows updater trusts the SHA-256 from Gitea's invite service.
        // Do not serve a differently-built ZIP claiming the same version.
        if (String(manifest.zip?.sha256).toLowerCase() !== String(latest.sha256).toLowerCase() || Number(manifest.zip?.size) !== Number(latest.size)) return origin();
      } else if (manifestResponse.status !== 404) {
        return origin();
      }

      const wizard = format === 'exe';
      const type = wizard ? 'setup' : 'zip';
      const ext = wizard ? '-Setup.exe' : '.zip';
      const object = manifest ? sanitizeAsset(manifest[type]?.file, version, ext) : `SwVault-${TEAM}-${version}${ext}`;
      if (!object) return origin();

      const assetUrl = `${R2_BASE}/${basePath}${object}`;
      const assetHeaders = new Headers();
      for (const header of ['range', 'if-range']) {
        const value = request.headers.get(header);
        if (value) assetHeaders.set(header, value);
      }
      const asset = await fetch(assetUrl, {method: request.method, headers: assetHeaders});
      if (![200, 206, 416].includes(asset.status)) return origin();
      if (asset.status === 416 && !request.headers.has('range')) return origin();
      if (asset.status === 200) {
        const expectedSize = manifest ? Number(manifest[type]?.size) : (wizard ? undefined : Number(latest.size));
        const size = Number(asset.headers.get('content-length'));
        if (expectedSize !== undefined && (!Number.isSafeInteger(size) || size !== expectedSize)) return origin();
      }

      // Installer uses filename to recover invite code. Do not pass it to the R2 URL.
      const code = (url.searchParams.get('invite') || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
      const suffix = code.length === 12 ? `-invite-${code.slice(0, 4)}-${code.slice(4, 8)}-${code.slice(8, 12)}` : '';
      const team = TEAM.replace(/[^A-Za-z0-9_-]/g, '');
      const filename = `SwVault-${team}${wizard ? '-Setup' : ''}${suffix}.${wizard ? 'exe' : 'zip'}`;
      return directResponse(request, asset, filename, 'r2');
    } catch (error) {
      console.error('R2 installer download fallback:', String(error));
      return origin();
    }
  }
};
